DROP TABLE IF EXISTS `fuel_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fuel_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `depot_id` bigint unsigned NOT NULL,
  `bus_id` bigint unsigned NOT NULL,
  `driver_id` bigint unsigned DEFAULT NULL,
  `bus_route_id` bigint unsigned DEFAULT NULL,
  `filled_on` date NOT NULL,
  `odometer` int unsigned NOT NULL,
  `litres` decimal(8,2) NOT NULL,
  `price_per_litre` decimal(8,2) NOT NULL,
  `total_cost` decimal(10,2) NOT NULL,
  `full_tank` tinyint(1) NOT NULL DEFAULT '1',
  `station` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `recorded_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fuel_logs_depot_id_foreign` (`depot_id`),
  KEY `fuel_logs_driver_id_foreign` (`driver_id`),
  KEY `fuel_logs_bus_route_id_foreign` (`bus_route_id`),
  KEY `fuel_logs_recorded_by_foreign` (`recorded_by`),
  KEY `fuel_logs_bus_id_odometer_index` (`bus_id`,`odometer`),
  KEY `fuel_logs_filled_on_index` (`filled_on`),
  CONSTRAINT `fuel_logs_bus_id_foreign` FOREIGN KEY (`bus_id`) REFERENCES `buses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fuel_logs_bus_route_id_foreign` FOREIGN KEY (`bus_route_id`) REFERENCES `bus_routes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fuel_logs_depot_id_foreign` FOREIGN KEY (`depot_id`) REFERENCES `depots` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fuel_logs_driver_id_foreign` FOREIGN KEY (`driver_id`) REFERENCES `drivers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fuel_logs_recorded_by_foreign` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=233 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
